#include <iostream>
#include <vector>
#include <string>
#include <cstring>
#include <iomanip>

float hex_to_float_le(std::string sub)
{
    uint32_t val = std::stoul(sub, nullptr, 16);
    val = ((val << 24) & 0xff000000) |
          ((val << 8) & 0x00ff0000) |
          ((val >> 8) & 0x0000ff00) |
          ((val >> 24) & 0x000000ff);

    float f;
    std::memcpy(&f, &val, sizeof(float));
    return f;
}

std::vector<float> hex_to_float_array(std::string hex_str)
{
    std::vector<float> result;
    if (hex_str.size() >= 2 && (hex_str[0] == '0' && (hex_str[1] == 'x' || hex_str[1] == 'X')))
    {
        hex_str = hex_str.substr(2);
    }
    for (size_t i = 0; i + 8 <= hex_str.length(); i += 8)
    {
        result.push_back(hex_to_float_le(hex_str.substr(i, 8)));
    }
    return result;
}

int main()
{
    std::string hex_str = "";
        std::vector<float>
            floats = hex_to_float_array(hex_str);

    std::cout << std::fixed << std::setprecision(8);
    for (size_t i = 0; i < floats.size(); ++i)
    {
        if (std::abs(floats[i]) < 1e-12)
            std::cout << "0";
        else
            std::cout << floats[i];
        if (i < floats.size() - 1)
            std::cout << ", ";
    }
    return 0;
}